select * from customer

--Q1. what is total revenue generated by male vs female customer?
select gender, SUM(purchase_amount) as revenue
from customer
group by gender

--Q2. which customers used discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer);

--Q3. Which are the top 5 product with the highest average review rating?
SELECT item_purchased, ROUND(AVG(review_rating)::numeric, 2) AS average_rating
from customer
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 10

--Q4. Compare the average purchase amounts between standard and express shipping
SELECT shipping_type, ROUND(AVG(purchase_amount)::numeric, 2) as average_purchase_amount
from customer
WHERE shipping_type IN ('Express', 'Standard')
GROUP BY shipping_type

--Q5. Do Subscribe customers spend more? compare average spend and total revenue 
-- between subscribers and non-subscribers.
SELECT subscription_status,COUNT(customer_id) AS total_customer, ROUND(AVG(purchase_amount) ::numeric, 2) AS average_spend, SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status

--Q6. which 5 product have the highest percentage of purchases with discounts applied
SELECT item_purchased, ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5

--Q7 Segment customers into new, Returning, and loyal based on their 
-- total number of previous purchases, and show the count of each segment.
WITH customer_type AS (
    SELECT customer_id, previous_purchases,
    CASE 
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment
    FROM customer
)

SELECT customer_segment, COUNT(*) AS "Number of Customers"
FROM customer_type
GROUP BY customer_segment;

--Q8 what are the top 3 most purchased product within each category? 
WITH item_counts AS (
SELECT category, item_purchased, 
COUNT(customer_id) as total_orders,
ROW_NUMBER() over(partition by category order by count(customer_id) DESC) as item_rank
FROM customer
GROUP BY category, item_purchased
)

select item_rank, category, item_purchased, total_orders 
from item_counts
WHERE item_rank <= 3;

--Q9 are customers who are repeat buyers (more than 5 previous purchases) 
--also likely to subsrcibe
SELECT subscription_status, count(customer_id) as repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status

--Q10 what is the revenue contribution of each age group?
SELECT age_group, SUM(purchase_amount) AS revenue_contribution
from customer
group by age_group
order by revenue_contribution desc